-- Service-only metadata snapshot. Caller permissions are checked by Reports server functions
-- before privileged import; no token, file contents, ID/tax data, IP or user agent is returned.
-- Rollback: REVOKE ALL ON FUNCTION public.reports_history_snapshot(date,date,jsonb,timestamptz) FROM service_role;
CREATE OR REPLACE FUNCTION public.reports_history_snapshot(_from date,_to date,_filters jsonb,_as_of timestamptz DEFAULT now()) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
DECLARE result jsonb; BEGIN
IF _from IS NULL OR _to IS NULL OR _from>_to OR _as_of IS NULL OR _filters->>'accounts' NOT IN ('real','test','all') THEN RAISE EXCEPTION 'REPORT_FILTER_INVALID: Choose valid report filters.'; END IF;
WITH roster AS MATERIALIZED (SELECT r FROM public.reports_people_rows(_from,_to,_filters,_as_of) r),
agency_scope AS MATERIALIZED (SELECT a.* FROM public.agencies a WHERE a.created_at<=_as_of AND (_filters->>'accounts'='all' OR a.is_test=(_filters->>'accounts'='test')) AND (jsonb_array_length(COALESCE(_filters->'agencies','[]'))=0 OR a.id::text IN (SELECT jsonb_array_elements_text(_filters->'agencies'))) AND (COALESCE(_filters->>'status','any')='any' OR (_filters->>'status'='paused' AND a.paused_at IS NOT NULL) OR (_filters->>'status'='suspended' AND a.status='suspended' AND a.paused_at IS NULL) OR (_filters->>'status'='active' AND a.status<>'suspended' AND a.paused_at IS NULL)) AND (COALESCE(_filters->>'joined','')='' OR to_char(a.created_at AT TIME ZONE 'Africa/Johannesburg','YYYY-MM')=_filters->>'joined') AND (COALESCE(_filters->>'account_type','all') IN ('all','agency_staff'))),
invites AS MATERIALIZED (
 SELECT i.id::text id,i.email,i.agency_id,i.created_at,i.first_sent_at,i.accepted_at,i.expires_at,i.status::text status,i.source,'agency_staff'::text typ,CASE WHEN i.kind='agency_onboarding' THEN 'agency' ELSE 'staff' END kind FROM public.agency_invitations i
 UNION ALL SELECT i.id::text,i.email,NULL::uuid,i.created_at,i.first_sent_at,i.accepted_at,i.expires_at,i.status::text,i.source,'talent','talent' FROM public.independent_talent_invitations i
 UNION ALL SELECT i.id::text,i.email,i.agency_id,i.created_at,i.first_sent_at,i.accepted_at,i.expires_at,i.status::text,'agency','talent',CASE WHEN p.kind='link_request' THEN 'connection' WHEN p.kind='inert' THEN 'inert' ELSE 'talent' END FROM public.talent_invitations i LEFT JOIN public.talent_invite_private p ON p.invitation_id=i.id),
scoped_invites AS MATERIALIZED (SELECT i.*,COALESCE((SELECT r.r->>'person_id' FROM roster r WHERE lower(btrim(r.r->>'email'))=lower(btrim(i.email)) LIMIT 1),'prospect:'||md5(lower(btrim(i.email)))) person_id FROM invites i WHERE i.created_at<=_as_of AND (_filters->>'accounts'='all' OR public.invitation_counts_as_test(i.email,i.agency_id)=(_filters->>'accounts'='test')) AND (_filters->>'account_type'='all' OR i.typ=_filters->>'account_type') AND (_filters->>'source'='all' OR i.source=_filters->>'source') AND (jsonb_array_length(COALESCE(_filters->'agencies','[]'))=0 OR i.agency_id::text IN (SELECT jsonb_array_elements_text(_filters->'agencies'))) AND ((COALESCE(_filters->>'joined','')='' AND COALESCE(_filters->>'status','any')='any' AND COALESCE(_filters->>'talent','all')='all' AND COALESCE(_filters->>'search','')='' AND jsonb_array_length(COALESCE(_filters->'people','[]'))=0) OR EXISTS(SELECT 1 FROM roster r WHERE lower(btrim(r.r->>'email'))=lower(btrim(i.email))))),
shares AS MATERIALIZED (SELECT s.*,t.user_id::text person_id,'recipient:'||md5(lower(btrim(s.loved_one_email))) recipient_id FROM public.loved_one_shares s JOIN public.talent_profiles t ON t.id=s.talent_id WHERE s.created_at<=_as_of AND EXISTS(SELECT 1 FROM roster r WHERE r.r->>'person_id'=t.user_id::text OR (r.r->>'person_id'='recipient:'||md5(lower(btrim(s.loved_one_email))) AND (_filters->>'accounts'='all' OR t.is_test=(_filters->>'accounts'='test'))))),
records AS (
 SELECT jsonb_build_object('id',r.r->>'person_id','person_id',r.r->>'person_id','at',r.r->>'registered_at','kind','registration','type',r.r->>'account_type') r FROM roster r WHERE (r.r->>'registered')::boolean
 UNION ALL SELECT jsonb_build_object('id',r.r->>'person_id','person_id',r.r->>'person_id','at',r.r->>'onboarded_at','kind','onboarding','type',r.r->>'account_type') FROM roster r WHERE r.r->>'onboarded_at' IS NOT NULL
 UNION ALL SELECT jsonb_build_object('id',i.id,'person_id',i.person_id,'agency_id',i.agency_id,'at',i.first_sent_at,'created_at',i.created_at,'accepted_at',i.accepted_at,'expires_at',i.expires_at,'kind','invitation','type',i.kind,'source',i.source,'status',CASE WHEN i.status='pending' AND i.expires_at<=_as_of THEN 'expired' ELSE i.status END) FROM scoped_invites i WHERE i.first_sent_at IS NOT NULL AND i.status<>'draft'
 UNION ALL SELECT jsonb_build_object('id',e.id,'person_id',e.actor_id,'at',e.created_at,'kind','sign_in','device',CASE WHEN COALESCE(e.detail->>'device',e.user_agent,'')~*'(mobile|android|iphone|ipad)' THEN 'mobile' WHEN COALESCE(e.detail->>'device',e.user_agent,'')<>'' THEN 'desktop' ELSE 'unknown' END,'new_device',COALESCE((e.detail->>'new_device')::boolean,false)) FROM public.reports_login_history() e WHERE e.created_at<=_as_of AND EXISTS(SELECT 1 FROM roster r WHERE r.r->>'person_id'=e.actor_id::text)
 UNION ALL SELECT jsonb_build_object('id',d.id,'person_id',d.user_id,'at',d.created_at,'kind','document','type',COALESCE(d.mime_type,'Unspecified'),'visibility','private','expires_at',d.expires_at,'validated',d.validated_at IS NOT NULL AND d.quarantine_reason IS NULL,'own',true) FROM public.talent_private_documents d WHERE d.created_at<=_as_of AND EXISTS(SELECT 1 FROM roster r WHERE r.r->>'person_id'=d.user_id::text)
 UNION ALL SELECT jsonb_build_object('id',d.id,'person_id',l.talent_user_id,'agency_id',d.agency_id,'at',d.created_at,'kind','document','type',COALESCE(d.mime_type,'Unspecified'),'visibility','shared','expires_at',d.validity_expires_at,'validated',d.validated_at IS NOT NULL AND d.quarantine_reason IS NULL,'own',d.uploaded_by=l.talent_user_id AND d.copied_from_vault_at IS NULL,'deleted_at',d.deleted_at) FROM public.talent_shared_documents d JOIN public.agency_talent_links l ON l.id=d.talent_link_id WHERE d.created_at<=_as_of AND (EXISTS(SELECT 1 FROM roster r WHERE r.r->>'person_id'=l.talent_user_id::text) OR (_filters->>'account_type' IN ('all','agency_staff') AND d.agency_id IN (SELECT id FROM agency_scope)))
 UNION ALL SELECT jsonb_build_object('id',s.id,'person_id',s.person_id,'recipient_id',s.recipient_id,'at',s.created_at,'kind','contact_share','expires_at',s.expires_at,'status',CASE WHEN s.revoked_at IS NOT NULL THEN 'revoked' WHEN s.expires_at<=_as_of THEN 'expired' ELSE 'active' END) FROM shares s
 UNION ALL SELECT jsonb_build_object('id',e.id,'person_id',s.recipient_id,'at',e.created_at,'kind',CASE WHEN e.event='successful_code' THEN 'contact_visit' ELSE 'contact_document' END,'type',e.event) FROM public.loved_one_share_access_events e JOIN shares s ON s.id=e.share_id WHERE e.created_at<=_as_of AND e.event IN ('successful_code','document_viewed','document_downloaded','view','download','document_opened')
 UNION ALL SELECT jsonb_build_object('id',l.id,'person_id',l.talent_user_id,'agency_id',l.agency_id,'at',l.created_at,'kind','agency_link','status',l.status,'ended_at',l.ended_at) FROM public.agency_talent_links l WHERE l.created_at<=_as_of AND (EXISTS(SELECT 1 FROM roster r WHERE r.r->>'person_id'=l.talent_user_id::text) OR l.agency_id IN (SELECT id FROM agency_scope))
 UNION ALL SELECT jsonb_build_object('id',d.id,'agency_id',d.agency_id,'person_id',l.talent_user_id,'at',d.issued_at,'kind',d.kind,'status',d.status,'value',d.total_cents,'currency',d.currency) FROM public.agency_billing_docs d LEFT JOIN public.agency_talent_links l ON l.id=d.talent_link_id WHERE d.agency_id IN (SELECT id FROM agency_scope) AND d.status<>'draft' AND d.issued_at IS NOT NULL AND d.issued_at<=(_as_of AT TIME ZONE 'Africa/Johannesburg')::date
 UNION ALL SELECT jsonb_build_object('id',p.id,'agency_id',p.agency_id,'at',p.paid_on,'kind','payment','value',p.amount_cents,'document_id',p.doc_id,'currency',d.currency) FROM public.agency_invoice_payments p JOIN public.agency_billing_docs d ON d.id=p.doc_id WHERE p.agency_id IN (SELECT id FROM agency_scope) AND p.paid_on<=(_as_of AT TIME ZONE 'Africa/Johannesburg')::date
 UNION ALL SELECT jsonb_build_object('id',a.id,'person_id',a.user_id,'agency_id',a.agency_id,'at',a.accepted_at,'kind','terms','type',a.doc_type,'version',a.version) FROM public.legal_acceptances a WHERE a.accepted_at<=_as_of AND EXISTS(SELECT 1 FROM roster r WHERE r.r->>'person_id'=a.user_id::text)
 UNION ALL SELECT jsonb_build_object('id',a.id,'person_id',a.actor_id,'agency_id',a.agency_id,'at',a.created_at,'kind','agency_activity','type',a.action,'target_type',a.target_type,'target_id',a.target_id) FROM public.agency_audit_log a WHERE a.created_at<=_as_of AND a.agency_id IN (SELECT id FROM agency_scope)
 UNION ALL SELECT jsonb_build_object('id',a.id,'person_id',a.actor_id,'at',a.created_at,'kind','vault_activity','type',a.action) FROM public.talent_audit_log a WHERE a.action<>'login' AND a.created_at<=_as_of AND EXISTS(SELECT 1 FROM roster r WHERE r.r->>'person_id'=a.actor_id::text)
)
SELECT jsonb_build_object('people',COALESCE((SELECT jsonb_agg(r) FROM roster),'[]'), 'agencies',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',a.id,'name',a.name,'created_at',a.created_at,'status',a.status,'is_test',a.is_test)) FROM agency_scope a),'[]'),'records',COALESCE((SELECT jsonb_agg(r) FROM records WHERE r->>'at' IS NOT NULL),'[]'),'launch',(SELECT value FROM public.platform_settings WHERE key='launch'),'contact_started_at',public.sign_in_capture_started_at(),'as_of',LEAST(_as_of,now())) INTO result;
RETURN result; END $fn$;
REVOKE ALL ON FUNCTION public.reports_history_snapshot(date,date,jsonb,timestamptz) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.reports_history_snapshot(date,date,jsonb,timestamptz) TO service_role;
